        <div data-action="bell" style="position:relative;width:44px;height:44px;border-radius:50%;background:#fff;border:1px solid rgba(15,23,42,.08);box-shadow:0 5px 16px -7px rgba(15,23,42,.22);display:flex;align-items:center;justify-content:center;cursor:pointer;">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M18 8.5a6 6 0 1 0-12 0c0 6-2.5 7.5-2.5 7.5h17S18 14.5 18 8.5" stroke="#0F172A" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"></path><path d="M13.6 20a1.9 1.9 0 0 1-3.2 0" stroke="#0F172A" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"></path></svg>
          <div data-ref="bellDotRef" style="position:absolute;top:9px;right:11px;width:9px;height:9px;border-radius:50%;background:#E31E24;border:2px solid #fff;box-shadow:0 0 6px rgba(227,30,36,.6);display:${a._showBellDot};"></div>
        </div>
